 const queued=async<T,>(fn:()=>Promise<T>):Promise<T>=>{busyRef.current++;setBusy(busyRef.current);let resolve!:(v:T)=>void,reject!:(e:any)=>void;const result=new Promise<T>((a,b)=>{resolve=a;reject=b});chain.current=chain.current.then(async()=>{try{if(!sessionMounted.current)throw new Error('账号会话已切换，此账号的未提交输入保留，操作未发出。');resolve(await fn())}catch(e){if((e as any).code==='NETWORK_ERROR')setOfflineSnapshot(true);notify((e as Error).message);reject(e)}finally{busyRef.current--;setBusy(busyRef.current)}});return result};
